// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }

    function testFuzz_property(address user) public {
        // Ensure user is a valid address that can call rely
        vm.assume(user != address(0) && user != address(this));

        // First, rely on the user via the auth mechanism
        // Since c is deployed with wards[msg.sender] = 1, we can call rely
        c.rely(user);

        // The rule: after calling rely(user), c.wards(user) must be 1
        assertTrue(c.wards(user) == 1);
    }
}

